examples.template:
VStack(alignment: .leading, spacing: theme.spacing.space3) {
    HStack(spacing: theme.spacing.space2) {
        ForEach(0...3, id: \.self) { count in
            MonarchButton(count == 0 ? "Nobody" : "\(count) typing", variant: typing == count ? .primary : .secondary, size: .sm) {
                typing = count
            }
        }
    }
    MonarchTypingIndicator(Array(names.prefix(typing)))
}

